package com.eduflow.backend;
import com.eduflow.backend.entity.*;
import com.eduflow.backend.repository.*;
import com.eduflow.backend.security.JwtService;
import com.eduflow.backend.service.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:exam-tests;MODE=MySQL;DB_CLOSE_DELAY=-1","app.exams.expiry-enabled=false"})
@AutoConfigureMockMvc @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class ExamManagementTests {
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JwtService jwt;
 @Autowired ExamRepository exams;@Autowired ExamQuestionRepository questions;@Autowired ExamOptionRepository options;@Autowired ExamAttemptRepository attempts;@Autowired ExamAnswerRepository answers;@Autowired ExamResultRepository results;@Autowired ExamResultCorrectionRepository corrections;@Autowired ExamAttemptService attemptService;
 @Autowired CourseRepository courses;@Autowired BatchRepository batches;@Autowired StudentRepository students;@Autowired TeacherRepository teachers;@Autowired UserRepository users;@Autowired BatchEnrollmentRepository enrollments;@Autowired BatchTeacherAssignmentRepository assignments;
 @MockitoBean(name="examClock") Clock clock;
 AtomicReference<Instant> time=new AtomicReference<>();Instant initial=Instant.parse("2026-11-09T09:00:00Z");
 String admin,teacher,otherTeacher,student,otherStudent,parent;Long batchId,studentId,otherStudentId;
 @BeforeEach void setup(){
  time.set(initial);when(clock.instant()).thenAnswer(x->time.get());clean();
  var ad=users.saveAndFlush(new User("Admin","admin@exam.test","unused",Role.ADMIN));admin=jwt.generateToken(ad.getEmail());
  var tu=users.saveAndFlush(new User("Teacher","teacher@exam.test","unused",Role.TEACHER));teacher=jwt.generateToken(tu.getEmail());
  users.saveAndFlush(new User("Other teacher","otherteacher@exam.test","unused",Role.TEACHER));otherTeacher=jwt.generateToken("otherteacher@exam.test");
  var su=users.saveAndFlush(new User("Student","student@exam.test","unused",Role.STUDENT));student=jwt.generateToken(su.getEmail());
  var ou=users.saveAndFlush(new User("Other","other@exam.test","unused",Role.STUDENT));otherStudent=jwt.generateToken(ou.getEmail());
  users.saveAndFlush(new User("Parent","parent@exam.test","unused",Role.PARENT));parent=jwt.generateToken("parent@exam.test");
  var c=new Course();c.setCode("EX");c.setName("Exam course");c.setDurationWeeks(12);courses.saveAndFlush(c);
  var b=new Batch();b.setCode("EX-B");b.setName("Exam batch");b.setCourse(c);b.setCapacity(20);b.setStartDate(LocalDate.of(2026,10,1));b.setEndDate(LocalDate.of(2027,1,31));b.setStatus(BatchStatus.ACTIVE);batches.saveAndFlush(b);batchId=b.getId();
  var t=new Teacher();t.setEmployeeId("EX-T");t.setFullName("Teacher");t.setEmail("faculty@exam.test");t.setUser(tu);teachers.saveAndFlush(t);
  var assignment=new BatchTeacherAssignment();assignment.setBatch(b);assignment.setTeacher(t);assignments.saveAndFlush(assignment);
  studentId=makeStudent("EX-1",su,b);otherStudentId=makeStudent("EX-2",ou,b);
 }
 Long makeStudent(String code,User u,Batch b){var s=new Student(code);s.setFullName(code);s.setEmail(code+"@student.test");s.setPhone("9876543210");s.setDateOfBirth(LocalDate.of(2008,1,1));s.setAdmissionDate(LocalDate.of(2026,10,1));s.setAddress("Address");s.setGuardianName("Guardian");s.setGuardianPhone("9876543211");s.setUser(u);students.saveAndFlush(s);var e=new BatchEnrollment();e.setBatch(b);e.setStudent(s);e.setEnrollmentDate(LocalDate.of(2026,10,1));enrollments.saveAndFlush(e);return s.getId();}
 @AfterEach void clean(){corrections.deleteAll();results.deleteAll();answers.deleteAll();attempts.deleteAll();options.deleteAll();questions.deleteAll();exams.deleteAll();assignments.deleteAll();enrollments.deleteAll();teachers.deleteAll();students.deleteAll();batches.deleteAll();courses.deleteAll();users.deleteAll();}
 MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b,Object data,String token)throws Exception{return b.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(data));}
 JsonNode body(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString());}
 Map<String,Object> input(String type){var r=new HashMap<String,Object>();r.put("examCode","EX-"+UUID.randomUUID().toString().substring(0,8));r.put("title","Assessment");r.put("batchId",batchId);r.put("examType",type);r.put("durationMinutes",30);r.put("totalMarks",10);r.put("passingMarks",5);r.put("startDateTime",initial.minusSeconds(60).toString());r.put("endDateTime",initial.plusSeconds(3600).toString());return r;}
 JsonNode create(String type)throws Exception{return body(mvc.perform(json(post("/api/exams"),input(type),admin)).andExpect(status().isCreated()).andReturn());}
 long version(long id)throws Exception{return body(mvc.perform(get("/api/exams/"+id).header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andReturn()).get("version").asLong();}
 Map<String,Object> question(long id,int marks)throws Exception{return new HashMap<>(Map.of("version",version(id),"questionText","Choose correct","marks",marks,"displayOrder",questions.findByExamIdOrderByDisplayOrderAscIdAsc(id).size()+1,"options",List.of(Map.of("optionText","Correct","correct",true),Map.of("optionText","Wrong","correct",false))));}
 JsonNode add(long id,int marks)throws Exception{return body(mvc.perform(json(post("/api/exams/"+id+"/questions"),question(id,marks),admin)).andExpect(status().isCreated()).andReturn());}
 long online()throws Exception{long id=create("ONLINE_MCQ").get("id").asLong();add(id,10);publish(id);return id;}
 void publish(long id)throws Exception{mvc.perform(json(post("/api/exams/"+id+"/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isOk());}
 JsonNode start(long id,String token)throws Exception{return body(mvc.perform(post("/api/exams/"+id+"/attempts/start").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn());}
 JsonNode save(JsonNode t,long qid,Long oid)throws Exception{var x=new HashMap<String,Object>();x.put("questionId",qid);x.put("selectedOptionId",oid);return body(mvc.perform(json(put("/api/exams/attempts/"+t.get("id").asLong()+"/answers"),Map.of("version",t.get("version").asLong(),"answers",List.of(x)),student)).andExpect(status().isOk()).andReturn());}
 void submit(JsonNode t)throws Exception{mvc.perform(post("/api/exams/attempts/"+t.get("id").asLong()+"/submit").header("Authorization","Bearer "+student)).andExpect(status().isOk());}
 long offline()throws Exception{long id=create("OFFLINE").get("id").asLong();publish(id);time.set(initial.plusSeconds(3601));return id;}
 Map<String,Object> marks(long id,int one,int two)throws Exception{return Map.of("version",version(id),"results",List.of(Map.of("studentId",studentId,"obtainedMarks",one),Map.of("studentId",otherStudentId,"obtainedMarks",two)));}
 void publishResults(long id)throws Exception{mvc.perform(json(post("/api/exams/"+id+"/results/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isOk());}
 @Test void createsOnlineOfflineAndFiltersPagination()throws Exception{create("ONLINE_MCQ");create("OFFLINE");mvc.perform(get("/api/exams").param("examType","OFFLINE").param("search","Assessment").param("size","1").header("Authorization","Bearer "+teacher)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(1));}
 @Test void validatesDatesMarksDurationAndDuplicateCode()throws Exception{var r=input("ONLINE_MCQ");r.put("endDateTime",initial.minusSeconds(90).toString());mvc.perform(json(post("/api/exams"),r,admin)).andExpect(status().isBadRequest());r=input("ONLINE_MCQ");r.put("durationMinutes",0);mvc.perform(json(post("/api/exams"),r,admin)).andExpect(status().isBadRequest());r=input("OFFLINE");r.put("passingMarks",11);mvc.perform(json(post("/api/exams"),r,admin)).andExpect(status().isBadRequest());r=input("OFFLINE");mvc.perform(json(post("/api/exams"),r,admin)).andExpect(status().isCreated());mvc.perform(json(post("/api/exams"),r,admin)).andExpect(status().isConflict());}
 @Test void unauthorizedRolesAndUnassignedTeacherDenied()throws Exception{long id=create("OFFLINE").get("id").asLong();for(String token:List.of(otherTeacher,student,parent)){mvc.perform(json(post("/api/exams"),input("OFFLINE"),token)).andExpect(status().isForbidden());mvc.perform(get("/api/exams/"+id).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());}mvc.perform(get("/api/exams")).andExpect(status().isUnauthorized());}
 @Test void draftHiddenAndAnswerKeysNeverAppearInStudentAttemptPayloads()throws Exception{long id=create("ONLINE_MCQ").get("id").asLong();add(id,10);mvc.perform(get("/api/exams").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));publish(id);var t=start(id,student);assertThat(t.findValues("correct")).isEmpty();assertThat(t.findValues("awardedMarks")).isEmpty();assertThat(t.findValues("obtainedMarks")).isEmpty();mvc.perform(get("/api/exams/"+id+"/questions").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());}
 @Test void questionValidationAndPublicationTotalRequired()throws Exception{long id=create("ONLINE_MCQ").get("id").asLong();mvc.perform(json(post("/api/exams/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isBadRequest());var q=question(id,10);q.put("options",List.of(Map.of("optionText","Only","correct",true)));mvc.perform(json(post("/api/exams/"+id+"/questions"),q,admin)).andExpect(status().isBadRequest());q.put("options",List.of(Map.of("optionText","One","correct",true),Map.of("optionText","Two","correct",true)));mvc.perform(json(post("/api/exams/"+id+"/questions"),q,admin)).andExpect(status().isBadRequest());add(id,9);mvc.perform(json(post("/api/exams/"+id+"/publish"),Map.of("version",version(id)),admin)).andExpect(status().isBadRequest());}
 @Test void publishedMetadataQuestionsAndCancellationWithHistoryImmutable()throws Exception{long id=online();var r=input("ONLINE_MCQ");r.put("version",version(id));mvc.perform(json(put("/api/exams/"+id),r,admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/exams/"+id+"/questions"),question(id,1),admin)).andExpect(status().isConflict());start(id,student);mvc.perform(json(post("/api/exams/"+id+"/cancel"),Map.of("version",version(id),"reason","Test"),admin)).andExpect(status().isConflict());}
 @Test void draftQuestionsEditableRemovableAndReorderable()throws Exception{long id=create("ONLINE_MCQ").get("id").asLong();var q1=add(id,4);var q2=add(id,6);mvc.perform(json(put("/api/exams/"+id+"/questions/order"),Map.of("version",version(id),"questionIds",List.of(q2.get("id").asLong(),q1.get("id").asLong())),teacher)).andExpect(status().isOk()).andExpect(jsonPath("$[0].id").value(q2.get("id").asLong()));mvc.perform(delete("/api/exams/"+id+"/questions/"+q1.get("id").asLong()).param("version",Long.toString(version(id))).header("Authorization","Bearer "+admin)).andExpect(status().isNoContent());assertThat(questions.count()).isEqualTo(1);}
 @Test void oneAttemptAndOwnerIsolation()throws Exception{long id=online();var t=start(id,student);assertThat(start(id,student).get("id")).isEqualTo(t.get("id"));mvc.perform(get("/api/exams/attempts/"+t.get("id").asLong()).header("Authorization","Bearer "+otherStudent)).andExpect(status().isForbidden());mvc.perform(post("/api/exams/attempts/"+t.get("id").asLong()+"/submit").header("Authorization","Bearer "+teacher)).andExpect(status().isForbidden());assertThat(attempts.count()).isEqualTo(1);}
 @Test void beforeStartAfterEndAndPreEnrollmentCannotStart()throws Exception{long id=online();time.set(initial.minusSeconds(120));mvc.perform(post("/api/exams/"+id+"/attempts/start").header("Authorization","Bearer "+student)).andExpect(status().isConflict());time.set(initial.plusSeconds(4000));mvc.perform(post("/api/exams/"+id+"/attempts/start").header("Authorization","Bearer "+student)).andExpect(status().isConflict());time.set(initial);var n=enrollments.findByBatchIdAndStudentIdOrderByEnrollmentDate(batchId,studentId).getFirst();n.setEnrollmentDate(LocalDate.of(2026,11,10));enrollments.saveAndFlush(n);mvc.perform(post("/api/exams/"+id+"/attempts/start").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());}
 @Test void deadlineIsEarlierOfDurationAndAvailabilityEnd()throws Exception{long id=online();var t=start(id,student);assertThat(Instant.parse(t.get("expiresAt").asText())).isEqualTo(initial.plusSeconds(1800));time.set(initial.plusSeconds(3500));var other=start(id,otherStudent);assertThat(Instant.parse(other.get("expiresAt").asText())).isEqualTo(initial.plusSeconds(3600));}
 @Test void savesAndClearsAnswersAndRejectsWrongQuestionOrOptionAtomically()throws Exception{long id=online();var t=start(id,student);var q=questions.findByExamIdOrderByDisplayOrderAscIdAsc(id).getFirst();long oid=options.findByQuestionIdOrderByDisplayOrder(q.getId()).getFirst().getId();t=save(t,q.getId(),oid);assertThat(t.get("answers")).hasSize(1);mvc.perform(json(put("/api/exams/attempts/"+t.get("id").asLong()+"/answers"),Map.of("version",t.get("version").asLong(),"answers",List.of(Map.of("questionId",99999,"selectedOptionId",oid))),student)).andExpect(status().isBadRequest());save(t,q.getId(),null);assertThat(answers.findAll().getFirst().getSelectedOption()).isNull();}
 @Test void correctWrongAndUnansweredAreGradedDeterministically()throws Exception{long id=create("ONLINE_MCQ").get("id").asLong();var q1=add(id,4);var q2=add(id,6);publish(id);var t=start(id,student);t=save(t,q1.get("id").asLong(),q1.at("/options/0/id").asLong());save(t,q2.get("id").asLong(),q2.at("/options/1/id").asLong());submit(t);submit(t);assertThat(results.findAll()).hasSize(1);assertThat(results.findAll().getFirst().getObtainedMarks()).isEqualByComparingTo("4");var other=start(id,otherStudent);mvc.perform(post("/api/exams/attempts/"+other.get("id").asLong()+"/submit").header("Authorization","Bearer "+otherStudent)).andExpect(status().isOk());assertThat(results.findByExamIdAndStudentId(id,otherStudentId).orElseThrow().getObtainedMarks()).isZero();}
 @Test void submittedAnswersImmutableAndStaleSavesRejected()throws Exception{long id=online();var t=start(id,student);var q=questions.findByExamIdOrderByDisplayOrderAscIdAsc(id).getFirst();long oid=options.findByQuestionIdOrderByDisplayOrder(q.getId()).getFirst().getId();save(t,q.getId(),oid);mvc.perform(json(put("/api/exams/attempts/"+t.get("id").asLong()+"/answers"),Map.of("version",0,"answers",List.of()),student)).andExpect(status().isConflict());submit(t);mvc.perform(json(put("/api/exams/attempts/"+t.get("id").asLong()+"/answers"),Map.of("version",1,"answers",List.of()),student)).andExpect(status().isConflict());}
 @Test void expiredSaveRejectsNewAnswersButCommitsAutoEvaluation()throws Exception{long id=online();var t=start(id,student);time.set(initial.plusSeconds(1800));mvc.perform(json(put("/api/exams/attempts/"+t.get("id").asLong()+"/answers"),Map.of("version",0,"answers",List.of()),student)).andExpect(status().isConflict()).andExpect(jsonPath("status").value("AUTO_SUBMITTED"));assertThat(results.count()).isEqualTo(1);assertThat(attempts.findAll().getFirst().getObtainedMarks()).isZero();}
 @Test void disconnectedAttemptsExpireWithoutStudentRequest()throws Exception{long id=online();var t=start(id,student);time.set(initial.plusSeconds(1801));attemptService.expire(t.get("id").asLong());assertThat(attempts.findAll().getFirst().getStatus()).isEqualTo(ExamAttemptStatus.AUTO_SUBMITTED);assertThat(results.count()).isEqualTo(1);}
 @Test void offlineBulkAtomicAndOnlyEligibleMarksAccepted()throws Exception{long id=offline();var invalid=Map.of("version",version(id),"results",List.of(Map.of("studentId",studentId,"obtainedMarks",7),Map.of("studentId",otherStudentId,"obtainedMarks",11)));mvc.perform(json(put("/api/exams/"+id+"/offline-results"),invalid,teacher)).andExpect(status().isBadRequest());assertThat(results.count()).isZero();mvc.perform(json(put("/api/exams/"+id+"/offline-results"),Map.of("version",version(id),"results",List.of(Map.of("studentId",99999,"obtainedMarks",5))),teacher)).andExpect(status().isBadRequest());mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,7,3),teacher)).andExpect(status().isOk());assertThat(results.count()).isEqualTo(2);}
 @Test void offlineEntryBeforeEndAndIncompletePublicationRejected()throws Exception{long id=create("OFFLINE").get("id").asLong();publish(id);mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,7,3),teacher)).andExpect(status().isConflict());time.set(initial.plusSeconds(4000));mvc.perform(json(put("/api/exams/"+id+"/offline-results"),Map.of("version",version(id),"results",List.of(Map.of("studentId",studentId,"obtainedMarks",7))),teacher)).andExpect(status().isOk());mvc.perform(json(post("/api/exams/"+id+"/results/publish"),Map.of("version",version(id)),teacher)).andExpect(status().isConflict());}
 @Test void unpublishedHiddenAndPublishedOwnReviewSecure()throws Exception{long id=online();var t=start(id,student);var q=questions.findByExamIdOrderByDisplayOrderAscIdAsc(id).getFirst();save(t,q.getId(),options.findByQuestionIdOrderByDisplayOrder(q.getId()).getFirst().getId());submit(t);mvc.perform(get("/api/exams/"+id+"/result").header("Authorization","Bearer "+student)).andExpect(jsonPath("published").value(false)).andExpect(jsonPath("result").isEmpty());mvc.perform(get("/api/exams/me/results").header("Authorization","Bearer "+student)).andExpect(jsonPath("totalElements").value(0));time.set(initial.plusSeconds(3601));publishResults(id);mvc.perform(get("/api/exams/"+id+"/result").header("Authorization","Bearer "+student)).andExpect(jsonPath("result.percentage").value(100)).andExpect(jsonPath("review[0].correctOptionId").isNumber());mvc.perform(get("/api/exams/"+id+"/results").header("Authorization","Bearer "+student)).andExpect(status().isForbidden());mvc.perform(get("/api/exams/results/students/"+studentId).header("Authorization","Bearer "+otherStudent)).andExpect(status().isForbidden());}
 @Test void publishedCorrectionsAuditedAndRankingTiesStable()throws Exception{long id=offline();mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,7,7),teacher)).andExpect(status().isOk());publishResults(id);mvc.perform(get("/api/exams/"+id+"/leaderboard").header("Authorization","Bearer "+teacher)).andExpect(jsonPath("content[0].rank").value(1)).andExpect(jsonPath("content[1].rank").value(1));mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,8,9),teacher)).andExpect(status().isConflict());long rid=results.findByExamIdAndStudentId(id,studentId).orElseThrow().getId();mvc.perform(json(post("/api/exams/"+id+"/results/"+rid+"/correct"),Map.of("version",version(id),"obtainedMarks",9,"reason","Rechecked paper"),teacher)).andExpect(status().isOk());assertThat(corrections.findAll().getFirst().getPreviousMarks()).isEqualByComparingTo("7");mvc.perform(get("/api/exams/"+id+"/results/"+rid+"/corrections").header("Authorization","Bearer "+teacher)).andExpect(jsonPath("$[0].reason").value("Rechecked paper"));}
 @Test void analyticsUsePublishedResultsAndScopeTeacherAndStudent()throws Exception{long id=offline();mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,8,2),teacher)).andExpect(status().isOk());publishResults(id);mvc.perform(get("/api/exams/analytics").header("Authorization","Bearer "+admin)).andExpect(status().isOk()).andExpect(jsonPath("scores.average").value(50)).andExpect(jsonPath("scores.passRate").value(50));mvc.perform(get("/api/exams/analytics").header("Authorization","Bearer "+otherTeacher)).andExpect(jsonPath("totalExams").value(0));mvc.perform(get("/api/exams/analytics").param("studentId",otherStudentId.toString()).header("Authorization","Bearer "+student)).andExpect(jsonPath("scores.average").value(80)).andExpect(jsonPath("trend.length()").value(1));}
 @Test void completedBatchAndLaterWithdrawalPreserveHistoricalResults()throws Exception{long id=offline();mvc.perform(json(put("/api/exams/"+id+"/offline-results"),marks(id,8,2),teacher)).andExpect(status().isOk());publishResults(id);var b=batches.findById(batchId).orElseThrow();b.setStatus(BatchStatus.COMPLETED);batches.saveAndFlush(b);var e=enrollments.findByBatchIdAndStudentIdOrderByEnrollmentDate(batchId,studentId).getFirst();e.setWithdrawalDate(LocalDate.of(2026,11,10));e.setStatus(EnrollmentStatus.WITHDRAWN);enrollments.saveAndFlush(e);mvc.perform(get("/api/exams/"+id+"/result").header("Authorization","Bearer "+student)).andExpect(status().isOk()).andExpect(jsonPath("result.obtainedMarks").value(8));}
 @Test void concurrentStartCreatesOnlyOneAttempt()throws Exception{long id=online();var latch=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){Callable<Long> run=()->{latch.await();return start(id,student).get("id").asLong();};var one=pool.submit(run);var two=pool.submit(run);latch.countDown();assertThat(one.get(20,TimeUnit.SECONDS)).isEqualTo(two.get(20,TimeUnit.SECONDS));assertThat(attempts.count()).isEqualTo(1);}}
}
